using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using BlockBlast.UI;
public static class UIArtVariants {
 const string Root="Assets/_Project/UI/Generated/";
 static Texture2D Read(Texture source,int width,int height){var rt=RenderTexture.GetTemporary(width,height,0);Graphics.Blit(source,rt);var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(width,height,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,width,height),0,0);t.Apply();RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);return t;}
 static Sprite Save(string name,Texture2D texture){var path=Root+name+".png";File.WriteAllBytes(path,texture.EncodeToPNG());Object.DestroyImmediate(texture);AssetDatabase.ImportAsset(path);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.textureType=TextureImporterType.Sprite;imp.spriteImportMode=SpriteImportMode.Single;imp.filterMode=FilterMode.Bilinear;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.mipmapEnabled=false;imp.spritePixelsPerUnit=100;var settings=new TextureImporterSettings();imp.ReadTextureSettings(settings);settings.spriteMeshType=SpriteMeshType.FullRect;imp.SetTextureSettings(settings);imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Sprite>(path);}
 public static string Generate(){var theme=AssetDatabase.LoadAssetAtPath<UITheme>("Assets/_Project/ScriptableObjects/UITheme.asset");var source=Read(theme.blockSprites[0].texture,theme.blockSprites[0].texture.width,theme.blockSprites[0].texture.height);
 for(int i=0;i<8;i++){var sprite=theme.blockSprites[i];Texture2D read=i<6?source:Read(sprite.texture,sprite.texture.width,sprite.texture.height);for(int state=1;state<=2;state++){var tex=new Texture2D(256,256,TextureFormat.RGBA32,false);var pixels=new Color[256*256];for(int y=0;y<256;y++)for(int x=0;x<256;x++){var r=sprite.rect;var c=read.GetPixel(Mathf.Clamp((int)(r.x+x/255f*(r.width-1)),0,read.width-1),Mathf.Clamp((int)(r.y+y/255f*(r.height-1)),0,read.height-1));if(state==1){float a=c.a;c=Color.Lerp(c,Color.white,.2f);c.a=a;}else{float v=c.grayscale;c=new Color(v*.65f,v*.65f,v*.65f,c.a);}pixels[y*256+x]=c;}tex.SetPixels(pixels);tex.Apply();var result=Save("Block"+i+(state==1?"Highlighted":"Disabled"),tex);if(state==1)theme.highlightedSprites[i]=result;else theme.disabledSprites[i]=result;}if(i>=6)Object.DestroyImmediate(read);}Object.DestroyImmediate(source);
 var background=GameObject.Find("Background").GetComponent<SpriteRenderer>().sprite;var full=Read(background.texture,background.texture.width,background.texture.height);var region=new Texture2D((int)background.rect.width,(int)background.rect.height,TextureFormat.RGBA32,false);region.SetPixels(full.GetPixels((int)background.rect.x,(int)background.rect.y,region.width,region.height));region.Apply();Object.DestroyImmediate(full);var blur=Read(region,415,430);Object.DestroyImmediate(region);for(int pass=0;pass<3;pass++){var old=blur.GetPixels();var output=new Color[old.Length];for(int y=0;y<blur.height;y++)for(int x=0;x<blur.width;x++){Color sum=Color.clear;int count=0;for(int dy=-3;dy<=3;dy++)for(int dx=-3;dx<=3;dx++){sum+=old[Mathf.Clamp(y+dy,0,blur.height-1)*blur.width+Mathf.Clamp(x+dx,0,blur.width-1)];count++;}output[y*blur.width+x]=sum/count;}blur.SetPixels(output);blur.Apply();}Save("BackgroundSoft",blur);EditorUtility.SetDirty(theme);AssetDatabase.SaveAssets();return "16 state variants and baked blur";}
}
